def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: int | float | None
    """
    if value is None:
        return None
    try:
        total_seconds = value.total_seconds()
    except AttributeError:
        return None
    if isinstance(total_seconds, float) and total_seconds.is_integer():
        return int(total_seconds)
    return total_seconds

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Accept None as neutral value
    if value is None:
        return None

    # Basic validation: must provide hour/minute/second attributes like a datetime.time
    required_attrs = ('hour', 'minute', 'second')
    if not all(hasattr(value, attr) for attr in required_attrs):
        raise TypeError("dehydrate_time requires a time-like object with hour, minute, and second attributes")

    try:
        # Most time objects provide isoformat which is a suitable dehydrated representation
        return value.isoformat()
    except Exception as e:
        # Fallback: format manually if isoformat is missing or broken
        try:
            if hasattr(value, 'microsecond') and getattr(value, 'microsecond', 0):
                return value.strftime('%H:%M:%S.%f')
            return value.strftime('%H:%M:%S')
        except Exception:
            # If we still cannot format, propagate the original exception
            raise e

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    # Ensure the value has the expected attributes
    try:
        lat = value.lat
        lon = value.lon
        time_val = value.time
    except AttributeError as exc:
        raise TypeError('Expected a Point (or Point-like) instance with attributes lat, lon, and time') from exc

    # Convert time to ISO 8601 string if possible
    if hasattr(time_val, 'isoformat'):
        time_str = time_val.isoformat()
    else:
        time_str = str(time_val)

    return {'lat': lat, 'lon': lon, 'time': time_str}

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve the record dictionary
        record = getattr(self, "_record", None)
        if record is None:
            return []

        # If the record is a dict, return its keys
        if isinstance(record, dict):
            return list(record.keys())

        # For objects that expose __dict__, return its public attributes
        if hasattr(record, "__dict__"):
            return [k for k in record.__dict__ if not k.startswith("_")]

        # Fallback to vars(record) for non-dict objects
        return list(vars(record).keys())
    except Exception:
        # In case of any unexpected errors, return an empty list
        return []

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        if hasattr(self, "_sort") and self._sort:
            return sorted_index(self._index, key)
        return self._index.index(key)
    except ValueError as exc:
        raise KeyError(f"{key!r} not found") from exc

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Ensure the object has an _items attribute which holds the data.
    if not hasattr(self, "_items"):
        raise AttributeError("The object does not expose an '_items' attribute required for values()")

    items = self._items

    # If no keys are specified, return all values.
    if not keys:
        if isinstance(items, dict):
            return list(items.values())
        try:
            # If the object behaves like a sequence, return its elements.
            return list(items)
        except TypeError:
            raise TypeError("Unsupported type for _items; must be a dict or sequence")

    # Otherwise, return only the requested values.
    result = []
    for k in keys:
        # Resolve string indices that look like integers.
        if isinstance(k, str) and k.isdigit():
            k = int(k)
        try:
            if isinstance(items, dict):
                if k in items:
                    result.append(items[k])
                else:
                    raise KeyError(f"Key '{k}' not found in _items")
            else:
                result.append(items[k])
        except (IndexError, KeyError, TypeError) as exc:
            raise TypeError(f"Unable to retrieve value for key/index '{k}': {exc}") from exc

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # The record is expected to store a list of values (self._values)
    # and a corresponding list of field names (self._keys).
    # If the record does not expose those attributes, we try to
    # deduce data from the instance's dictionary.
    try:
        values = self._values
        keys_list = self._keys
    except AttributeError:
        # Fall back: use attributes directly stored in the instance.
        # Assume any sequence attribute ending with '_data' is the values
        # and an attribute with the same base name ending with '_names' is the names.
        names_attr_candidates = [att for att in dir(self) if att.endswith('_names')]
        data_attr_candidates = [att for att in dir(self) if att.endswith('_data')]
        if names_attr_candidates and data_attr_candidates:
            keys_list = getattr(self, names_attr_candidates[0])
            values = getattr(self, data_attr_candidates[0])
        else:
            raise AttributeError(
                "Record object does not expose '_keys' and '_values' "
                "or corresponding '_names' and '_data' attributes"
            )

    if not isinstance(keys_list, (list, tuple)):
        keys_list = list(keys_list)
    if not isinstance(values, (list, tuple)):
        values = list(values)

    # Build a mapping from key to index for quick lookup when keys are strings.
    key_to_index = {key: idx for idx, key in enumerate(keys_list)}

    # If no specific keys requested, return all items.
    if not keys:
        return {name: val for name, val in zip(keys_list, values)}

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Index is requested.
            if k < 0 or k >= len(values):
                raise IndexError(f'Index {k} out of bounds for record of length {len(values)}')
            name = keys_list[k]
            result[name] = values[k]
        else:
            # Treat k as a key/name.
            idx = key_to_index.get(k)
            if idx is None:
                # Key not present in the record – insert None as per spec.
                result[k] = None
            else:
                result[k] = values[idx]
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer. """
    if not hasattr(self, 'data') or not isinstance(self.data, (bytes, bytearray)):
        raise AttributeError("Instance must have a 'data' attribute of type bytes or bytearray.")
    if len(self.data) < 2:
        raise ValueError("Insufficient data: cannot pop 2 bytes from an empty or too-short buffer.")
    last_bytes = self.data[-2:]
    del self.data[-2:]
    return int.from_bytes(last_bytes, byteorder='big', signed=False)

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")

    # Build the discard command payload
    msg = {
        'command': 'DISCARD',
        'n': n,
        'qid': qid
    }

    # Recursively apply dehydration hooks to any complex structures
    def _apply_hooks(value, hooks):
        if isinstance(value, dict):
            return {k: _apply_hooks(v, hooks) for k, v in value.items()}
        if isinstance(value, (list, tuple)):
            return type(value)(_apply_hooks(v, hooks) for v in value)
        if hooks:
            for typ, func in hooks.items():
                if isinstance(value, typ):
                    return func(value)
        return value

    if dehydration_hooks:
        msg = _apply_hooks(msg, dehydration_hooks)

    # Append the message to the output queue.
    # The consuming code will handle serialization and dispatch.
    if hasattr(self, "_output_queue"):
        try:
            self._output_queue.append(msg)
        except Exception as exc:
            raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc
    else:
        raise AttributeError("No output queue available to enqueue message")

    # Lightweight Response object to hold callbacks/hydration info
    class Response:
        def __init__(self, handlers, dehydration_hooks, hydration_hooks):
            self.handlers = handlers
            self.dehydration_hooks = dehydration_hooks
            self.hydration_hooks = hydration_hooks

    return Response(handlers, dehydration_hooks, hydration_hooks)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Normalise mode
        if mode is None:
            mode = "WRITE"
        else:
            mode = mode.upper()
            if mode not in ("READ", "WRITE"):
                raise ValueError("mode must be 'READ' or 'WRITE'")

        # Build the request body
        body = {"mode": mode}
        if bookmarks:
            try:
                body["bookmarks"] = list(bookmarks)
            except TypeError as exc:
                raise ValueError("bookmarks must be iterable") from exc
        if metadata:
            if not isinstance(metadata, dict):
                raise ValueError("metadata must be a dictionary")
            body["metadata"] = metadata
        if timeout is not None:
            body["timeout"] = float(timeout)
        if db:
            body["db"] = db
        if imp_user:
            body["imp_user"] = imp_user
        if dehydration_hooks:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            body["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            body["hydration_hooks"] = hydration_hooks

        # Create the BEGIN frame
        begin_frame = {"type": "BEGIN", "body": body}

        # Append to the output queue; assume _output_queue exists
        self._output_queue.put(begin_frame)

        # Return a Response wrapper; Response expects the original payload and handlers
        return Response(begin_frame, **handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    def _decorator(func):
        @functools.wraps(func)
        def _wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        # Add the message to the function's docstring for introspection.
        original_doc = func.__doc__ or ""
        separator = "\n\n" if original_doc else ""
        _wrapper.__doc__ = f"{original_doc}{separator}{message}"
        return _wrapper

    return _decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not s:
        return ()

    # Split on any non-digit characters (e.g., '.' '-' '+') and convert to integers
    try:
        import re
        parts = re.split(r'\D+', s)
    except Exception:
        # Fallback to simple split on period if regex fails
        parts = s.replace('-', '.').split('.')

    nums = []
    for part in parts:
        if part == '':
            continue
        try:
            nums.append(int(part))
        except ValueError:
            # Ignore non-numeric components (should not occur but safety)
            continue
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    maxsize = int(maxsize) if maxsize is not None else 0
    if maxsize < 0:
        raise ValueError("maxsize must be None or a non-negative integer")

    def _make_key(args, kwds, typed):
        # Build a key from positional and keyword arguments.
        # Add type information if typed=True.
        if kwds:
            kw_items = tuple(sorted(kwds.items()))
        else:
            kw_items = ()
        key = args + kw_items
        if typed:
            key += tuple(type(v) for v in args)
            key += tuple(type(v) for _, v in kw_items)
        return key

    def decorator(fn):
        from collections import OrderedDict
        cache = OrderedDict()

        @functools.wraps(fn)
        def wrapper(*a, **kw):
            key = _make_key(a, kw, typed)
            if key in cache:
                # Move to end to mark as most recently used
                val = cache.pop(key)
                cache[key] = val
                return val
            val = fn(*a, **kw)
            if maxsize > 0:
                if len(cache) >= maxsize:
                    # Evict the most recently used item (last)
                    cache.popitem(last=True)
            cache[key] = val
            return val

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        if maxsize <= 0:
            # No caching if zeroth or negative
            return func

        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            # Build the key
            if typed:
                key = tuple((type(v), v) for v in args)
                if kwargs:
                    kw_items = tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
                    key += kw_items
            else:
                key = args
                if kwargs:
                    kw_items = tuple(sorted(kwargs.items()))
                    key += kw_items

            # Try to fetch from cache
            if key in cache:
                # Move the key to the end to mark as recently used
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return cache[key]

            # Compute the value, store it
            value = func(*args, **kwargs)
            cache[key] = value
            order.append(key)

            # Evict the least recently used item if cache too big
            if len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)

            return value

        return wrapper

    return decorator

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    # Basic validation for the key type
    if not isinstance(key, str):
        raise TypeError("setdefault: key must be a string")

    # Retrieve the underlying dictionary attribute
    try:
        storage = self.storage
    except AttributeError as exc:
        raise AttributeError("setdefault requires an instance attribute 'storage'") from exc

    # Use the dictionary's get method to retrieve the current value
    value = storage.get(key, default)

    # If the key was not present, insert the default and mark the object as changed
    if key not in storage:
        storage[key] = default
        # Mark persistence flag if available
        if hasattr(storage, "_p_changed"):
            storage._p_changed = True

    return value

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not file_name or not isinstance(file_name, str):
        return False
    try:
        return os.path.isfile(os.path.realpath(file_name))
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all existing handlers
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                pass
        # Reconfigure root logger with default settings
        logging.basicConfig(level=logging.WARNING, handlers=[logging.StreamHandler()])
    except Exception as exc:
        # If any error occurs during resetting, log it using a fallback logger
        fallback_logger = logging.getLogger("fallback")
        if not fallback_logger.handlers:
            fallback_logger.addHandler(logging.StreamHandler())
            fallback_logger.setLevel(logging.ERROR)
        fallback_logger.error("Failed to reset logging configuration: %s", exc)

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    # Determine a deterministic priority for nodes based on first appearance
    rank = {}
    r = 0
    for ordering in orderings:
        for obj in ordering:
            if obj not in rank:
                rank[obj] = r
                r += 1

    # Build directed graph edges from each adjacency pair
    from collections import defaultdict
    graph = defaultdict(set)     # node -> set of successors
    indegree = defaultdict(int)  # node -> number of incoming edges
    nodes = set()

    for ordering in orderings:
        for i in range(len(ordering) - 1):
            a, b = ordering[i], ordering[i + 1]
            if b not in graph[a]:
                graph[a].add(b)
                indegree[b] += 1
                nodes.update((a, b))

    # Ensure nodes with no edges are represented
    for ordering in orderings:
        nodes.update(ordering)
        for obj in ordering:
            indegree.setdefault(obj, 0)

    # Perform a deterministic topological sort using node priority
    result = []
    zero = [node for node in nodes if indegree[node] == 0]
    zero.sort(key=lambda x: rank.get(x, 0))

    while zero:
        node = zero.pop(0)
        result.append(node)
        for nb in graph[node]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                zero.append(nb)
        zero.sort(key=lambda x: rank.get(x, 0))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in orderings")
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names = []
    seen = set()

    # Include instance-specific attributes
    try:
        for name in getattr(self, "__dict__", {}):
            if not all and name.startswith("_"):
                continue
            if name not in seen:
                seen.add(name)
                names.append(name)
    except Exception:
        pass

    try:
        cls = getattr(self, "__class__", type(self))
        # Class-defined attributes
        for name, value in getattr(cls, "__dict__", {}).items():
            if not all and name.startswith("_"):
                continue
            if callable(value):
                continue
            if name not in seen:
                seen.add(name)
                names.append(name)
        # Include inherited attributes if requested
        if all:
            for base in getattr(cls, "__mro__", ()):
                for name, value in getattr(base, "__dict__", {}).items():
                    if name.startswith("_"):
                        continue
                    if callable(value):
                        continue
                    if name not in seen:
                        seen.add(name)
                        names.append(name)
    except Exception:
        pass

    return names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]
    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)
    return output

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    # If a flag indicating required optimizations exists, reset it.
    if hasattr(self, "_c_optimizations_required"):
        self._c_optimizations_required = False
    # Optionally set a flag indicating that optimizations are ignored.
    if hasattr(self, "_c_optimizations_ignored"):
        self._c_optimizations_ignored = True
    return None

def _c_optimizations_required():
    """Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, default to requiring C optimizations
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value"):
        # If initial_value is a scalar, fill all bins with it
        if isinstance(self.initial_value, (int, float)):
            # Preserve the current bin count
            self.bins = [self.initial_value for _ in self.bins]
        else:
            # For iterable initial values, try to copy the iterable
            try:
                self.bins = list(self.initial_value)
            except Exception:
                # Fallback to the raw value if conversion fails
                self.bins = self.initial_value
    elif hasattr(self, "make_bins") and callable(self.make_bins):
        # Use the provided make_bins factory to generate fresh bins
        self.bins = self.make_bins()
    else:
        # No explicit reinitialisation strategy: clear bins
        self.bins = []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Attempt to retrieve the error indices mapping
    try:
        err_mapping = self._err_indices  # expecting a dict-like container
    except AttributeError:
        # The object doesn't hold error indices; return an empty array
        return np.array([], dtype=int)

    # If no error mapping for this coordinate, return empty array
    try:
        idx = err_mapping[coord_name]
    except KeyError:
        return np.array([], dtype=int)

    # Ensure the retrieved indices are array-like
    if isinstance(idx, (list, np.ndarray)):
        return np.asarray(idx, dtype=int)
    else:
        raise ValueError(f"Error indices for coordinate '{coord_name}' must be list or array, got {type(idx).__name__}")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Check for a single FillRequest element first
    if isinstance(seq, FillRequest):
        return True
    # Reject a Source sequence outright
    if isinstance(seq, Source):
        return False
    # For iterables, determine if they contain at least one FillRequest
    # while ignoring string and bytes types
    try:
        from collections.abc import Iterable
        if isinstance(seq, Iterable) and not isinstance(seq, (str, bytes)):
            return any(isinstance(item, FillRequest) for item in seq)
    except Exception:
        # In case of any unexpected iterable issues, fall back to False
        pass
    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        method = getattr(obj, "run")
        return callable(method)
    except AttributeError:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    if obj is None:
        return False
    try:
        fill = getattr(obj, 'fill', None)
        compute = getattr(obj, 'compute', None)
        return callable(fill) and callable(compute)
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    # Stop recursion if level is 0 (no deeper comparison)
    if level == 0:
        return {}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key only in d1 – include it
            result[key] = val1
        else:
            val2 = d2[key]
            # Both values are dicts: recurse if allowed
            if isinstance(val1, dict) and isinstance(val2, dict):
                next_level = -1 if level == -1 else level - 1
                subdiff = difference(val1, val2, next_level)
                if subdiff:
                    result[key] = subdiff
            # Values are not both dicts: compare directly
            else:
                if val1 != val2:
                    result[key] = val1
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    # Basic regex for allowed labels: keys must start with a letter and contain
    # letters, digits, or underscores. Adjust as needed.
    _LABEL_REGEX = re.compile(r'^[A-Za-z][A-Za-z0-9_]{0,63}$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({key_str: 'expected string or bytes-like object'})
        else:
            try:
                if not _LABEL_REGEX.search(key):
                    errors.append(
                        {key_str: f"Label key '{key}' does not match the regex { _LABEL_REGEX.pattern }"}
                    )
            except TypeError:
                errors.append({key_str: 'expected string or bytes-like object'})

        # Validate value type
        # For values that are collections (list/tuple/set/dict), we simply treat the
        # collection itself as the value to avoid lengthy recursion.
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            try:
                if not _LABEL_REGEX.search(value):
                    errors.append(
                        {str(value): f"Label value '{value}' does not match the regex { _LABEL_REGEX.pattern }"}
                    )
            except TypeError:
                errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    for key, value in manifest_dict.items():
        # If the value is a dict, recurse
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # Preserve only the identifying subfields 'name' and 'namespace'
                meta = {}
                if "name" in value:
                    meta["name"] = value["name"]
                if "namespace" in value:
                    meta["namespace"] = value["namespace"]
                result[key] = meta
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # If the value is a list, generate a list with the default of the first element
        elif isinstance(value, list):
            if not value:
                result[key] = []
            else:
                first_item = value[0]
                if isinstance(first_item, dict):
                    result[key] = [
                        generate_default_observer_schema_dict(first_item, first_level=False)
                    ]
                else:
                    result[key] = [None]
        # Scalar values: replace with None or copy for top‑level identifying fields
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present

    """
    # Basic sanity checks – the function works with dicts internally.
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            "last_applied_manifest must be a dict, got %s" % type(last_applied_manifest)
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            "observer_schema must be a list, got %s" % type(observer_schema)
        )
    if not isinstance(response, dict):
        raise TypeError(
            "response must be a dict, got %s" % type(response)
        )

    for item in observer_schema:
        # Primitive–scalar field specified by a string key
        if isinstance(item, str):
            key = item
            if key not in last_applied_manifest:
                # Initialise with a copy of the response value if present,
                # otherwise None.
                last_applied_manifest[key] = response.get(key, None)
            continue

        # Nested or complex field – the schema dict is expected to contain
        # a ``name`` key and optionally a ``schema`` key for further nesting.
        if isinstance(item, dict):
            key = item.get("name")
            sub_schema = item.get("schema")

            if key is None:
                continue  # nothing to process

            # Initialise the key if missing
            if key not in last_applied_manifest:
                # Default initial value is the type of the sub‑schema
                if isinstance(sub_schema, list):
                    last_applied_manifest[key] = []
                else:
                    last_applied_manifest[key] = {}

            # If the sub‑schema exists, recurse into the appropriate helper
            # based on the type of the existing value.
            if sub_schema and isinstance(sub_schema, list):
                # The field is a list – recurse into each element
                # Ensure we have a list to recurse into
                if not isinstance(last_applied_manifest[key], list):
                    last_applied_manifest[key] = []
                if key in response:
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[key], sub_schema, response[key]
                    )
            elif sub_schema and isinstance(sub_schema, dict):
                # The field is a dict – recurse with the dict schema
                if not isinstance(last_applied_manifest[key], dict):
                    last_applied_manifest[key] = {}
                if key in response:
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], sub_schema, response[key]
                    )
            else:
                # No sub‑schema – simple copy if present
                if key in response:
                    last_applied_manifest[key] = response[key]
        else:
            # Ignore items that are neither strings nor dicts
            continue

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Retrieve the application spec
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("Application object does not have a 'spec' attribute")

        # Manifest list contains the Kubernetes resources to observe
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("Spec does not contain a 'manifest' attribute")
        if not isinstance(manifest, list):
            raise TypeError("Spec.manifest should be a list of resource dictionaries")

        # Existing observer schemas (may be None or a dict)
        existing = getattr(spec, "observers", None)
        if existing is None:
            existing = {}
        if not isinstance(existing, dict):
            raise TypeError("Spec.observers should be a dictionary mapping kind to schema")

        # Build default schemas for missing kinds
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            if kind not in existing:
                # Very minimal default schema: an object with a 'status' property
                default_schema = {"type": "object", "properties": {"status": {"type": "object"}}}
                existing[kind] = default_schema

        # Attach the updated observers back to the spec
        setattr(spec, "observers", existing)
        return existing

    except Exception as exc:
        raise RuntimeError(f"Failed to generate default observer schemas: {exc}") from exc

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    try:
        # Determine whether path is a filesystem path or a pyfs root
        if isinstance(path, str):
            # Local filesystem path
            if not os.path.isdir(path):
                return False
            fs = None
            root_path = path
        else:
            # Assume pyfs filesystem root
            fs = path
            root_path = ""

        # Helper to build path relative to root
        def rel(p):
            return os.path.join(root_path, p) if fs is None else p

        # Check existence of .ocfl_version file
        version_path = rel(".ocfl_version")
        if fs:
            if not fs.exists(version_path):
                return False
            try:
                with fs.open(version_path, "r") as f:
                    json.loads(f.read())
            except Exception:
                return False
        else:
            if not os.path.isfile(version_path):
                return False
            try:
                with open(version_path, "r") as f:
                    json.loads(f.read())
            except Exception:
                return False

        # Check objects directory
        objects_dir = rel("objects")
        if fs:
            if not fs.isdir(objects_dir):
                return False
            # At least one object directory must exist
            try:
                subdirs = [
                    d
                    for d in fs.listdir(objects_dir)
                    if fs.isdir(fs.path.join(objects_dir, d))
                ]
            except Exception:
                return False
            if not subdirs:
                return False
        else:
            objects_dir_path = os.path.join(root_path, "objects")
            if not os.path.isdir(objects_dir_path):
                return False
            subdirs = [
                d
                for d in os.listdir(objects_dir_path)
                if os.path.isdir(os.path.join(objects_dir_path, d))
            ]
            if not subdirs:
                return False

        # If all checks pass, the object is considered valid
        return True
    except Exception:
        # Any unexpected error is treated as invalid
        return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to retrieve the log from common attribute names
    log = getattr(self, 'log', None) or getattr(self, 'validation_log', None)
    if not log:
        return ''
    # If it's already a string, return it directly
    if isinstance(log, str):
        return log
    # Build a string from each entry, adding the optional prefix
    parts = []
    for entry in log:
        try:
            entry_str = str(entry)
        except Exception:
            entry_str = repr(entry)
        parts.append(f'{prefix}{entry_str}')
    return '\n'.join(parts)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dictionary
    if not isinstance(inventory, dict):
        raise TypeError(f"Inventory must be a dict, got {type(inventory).__name__}")

    # Determine spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get('type')
        if isinstance(type_value, str):
            try:
                spec_version = int(type_value)
            except ValueError:
                # Keep the default spec_version
                pass
        elif isinstance(type_value, (int, float)):
            spec_version = int(type_value)

    # Retrieve the appropriate spec for this version
    spec = self._specs.get(spec_version)
    if spec is None:
        raise ValueError(f"Unsupported spec version {spec_version}")

    # Validate required fields
    required_fields = spec.get('required', [])
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")

    # Validate field types and other constraints
    field_defs = spec.get('fields', {})
    for field, definition in field_defs.items():
        if field not in inventory:
            # If the field is optional, skip further checks
            if definition.get('required', False):
                raise ValueError(f"Missing required field: {field}")
            continue

        value = inventory[field]
        expected_type = definition.get('type')
        if expected_type and not isinstance(value, expected_type):
            raise TypeError(
                f"Field '{field}' expected type {expected_type.__name__}, "
                f"got {type(value).__name__}"
            )

        # Potential place for additional validation logic
        # e.g., range checks, format checks, nested validations, etc.
        # For brevity, only type checking is performed here.

    # If all checks pass, return the inventory
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, (list, tuple)):
        raise TypeError("manifest_files must be a list or tuple of manifest entries")
    # Extract set of required digests from manifest entries
    try:
        required = {entry['digest'] for entry in manifest_files}
    except (TypeError, KeyError):
        raise ValueError("Each manifest entry must be a mapping containing a 'digest' key")
    # Ensure digests_used is a set for set operations
    used = set(digests_used) if digests_used else set()
    # Check for missing digests
    missing = required - used
    if missing:
        raise ValueError(f"Missing digests in used list: {missing}")
    # Return unused digests (optional helper)
    return used - required

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _parse_version(v):
        """Parse a version string into a tuple suitable for comparison."""
        parts = str(v).split(".")
        parsed = []
        for part in parts:
            try:
                parsed.append(int(part))
            except ValueError:
                # If part is not purely numeric, keep it as string
                parsed.append(part)
        return tuple(parsed)

    target = _parse_version(version)
    result = {}

    for logical_path, entries in inventory.items():
        file_set = set()
        for entry in entries:
            try:
                if isinstance(entry, dict):
                    ver = entry.get("version")
                    path = entry.get("content_file") or entry.get("path")
                elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    ver, path = entry[0], entry[1]
                else:
                    continue
                if ver is None or path is None:
                    continue
                entry_ver = _parse_version(ver)
                if entry_ver >= target:
                    file_set.add(path)
            except Exception:
                # Skip malformed entries silently
                continue
        if file_set:
            result[logical_path] = file_set
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure that fixity is a dictionary mapping file names to hashes
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary of file names to hashes")

    # Ensure manifest_files is iterable, turn into a set for fast lookup
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("manifest_files must be an iterable of file names")

    # Find any file names referenced in fixity that are not in the manifest
    invalid_refs = set(fixity) - manifest_set
    if invalid_refs:
        raise ValueError(
            f"Fixity block references unknown files: {', '.join(sorted(invalid_refs))}"
        )

    # Validate each hash value: must be a non-empty string of hex digits
    for fname, hash_val in fixity.items():
        if not isinstance(hash_val, str) or not hash_val:
            raise ValueError(
                f"Hash for file '{fname}' must be a non-empty string"
            )
        # Simple hex digit check – allows both upper and lower case
        if not all(c in "0123456789abcdefABCDEF" for c in hash_val):
            raise ValueError(
                f"Hash for file '{fname}' contains non-hexadecimal characters: {hash_val}"
            )

    return True

def files_list(path):
    """Return the files in `path`"""
    # If path does not exist, raise FileNotFoundError
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")

    # If it's a file, return it as a list
    if os.path.isfile(path):
        return [os.path.abspath(path)]

    # If it's a directory, list all files inside (non-recursively)
    if os.path.isdir(path):
        try:
            return [
                os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))
            ]
        except OSError:
            # If something goes wrong accessing the directory, return an empty list
            return []

    # For any other type, return an empty list
    return []

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language argument
    if not isinstance(lang, str) or not lang:
        raise ValueError("lang must be a non-empty string")

    # Validate file_path argument
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File '{file_path}' does not exist")

    # Infer the original filename by stripping the language suffix
    base_name = os.path.basename(file_path)
    name_part, ext = os.path.splitext(base_name)
    if name_part.endswith(f"-{lang}"):
        original_name = name_part[:-(len(lang) + 1)] + ext
    else:
        original_name = base_name

    # Ensure the container exists
    if not hasattr(self, "renditions") or not isinstance(self.renditions, dict):
        self.renditions = {}

    # Create or update the mapping for the original file
    if original_name not in self.renditions:
        self.renditions[original_name] = {}
    self.renditions[original_name][lang] = file_path

    return self.renditions[original_name]

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        # Open the zip file for reading
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Gather all entry names and their raw contents
            contents = {info.filename: zf.read(info) for info in zf.infolist()}

            # Identify XML files and group related files by the XML basename
            for xml_name in filter(lambda n: n.lower().endswith(".xml"), contents):
                base = os.path.splitext(os.path.basename(xml_name))[0]
                if base not in result:
                    result[base] = {}

                # Add all files that share the same basename (including the XML file)
                for fname, data in contents.items():
                    if os.path.splitext(os.path.basename(fname))[0] == base:
                        result[base][fname] = data
    except (FileNotFoundError, zipfile.BadZipFile, Exception):
        # If the file cannot be read or is not a valid ZIP, return an empty dict
        return {}
    return result

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if not isinstance(content, str):
        raise TypeError('content must be a string')
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not node or not pubdate_xpaths:
        return None
    for xpath_expr in pubdate_xpaths:
        try:
            result = node.xpath(xpath_expr)
            if result:
                return result[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        import pprint
        if not isinstance(indent, int) or indent < 0:
            indent = 0
        if debug:
            info = {
                'type': type(self).__qualname__,
                'repr': repr(self),
                'attributes': {}
            }
            # Safely get the instance dictionary if available
            attrs = getattr(self, "__dict__", {})
            for name, value in attrs.items():
                try:
                    info['attributes'][name] = pprint.pformat(value, indent=indent)
                except Exception:
                    info['attributes'][name] = repr(value)
            result = pprint.pformat(info, indent=indent)
        else:
            result = pprint.pformat(self, indent=indent)
    except Exception:
        result = repr(self)
    return result

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.
    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).
    :param dt: A timezone-aware :class:`datetime.datetime` object.
    """
    if dt.tzinfo is None:
        raise TypeError("_fromutc requires a timezone‑aware datetime")

    # Ensure dt is in UTC so we can compute local time reliably
    if dt.tzinfo.utcoffset(dt) is not None and dt.tzinfo.utcoffset(dt).total_seconds() != 0:
        dt = dt.astimezone(tzutc())

    # Work with the naive representation of the time
    naive = dt.replace(tzinfo=None)

    # Try both fold options to see if they give the same offset
    try:
        naive_fold0 = naive.replace(fold=0)
    except AttributeError:
        naive_fold0 = naive
    try:
        naive_fold1 = naive.replace(fold=1)
    except AttributeError:
        naive_fold1 = naive

    try:
        offset0 = self.utcoffset(naive_fold0)
    except Exception:
        offset0 = None
    try:
        offset1 = self.utcoffset(naive_fold1)
    except Exception:
        offset1 = None

    # If offsets are identical, this time is not ambiguous
    if offset0 == offset1:
        return naive.replace(tzinfo=self)

    # Ambiguous case: decide which fold matches the original UTC time
    cand0 = naive_fold0.replace(tzinfo=self)
    cand1 = naive_fold1.replace(tzinfo=self)
    try:
        if cand0.astimezone(tzutc()) == dt:
            return cand0
    except Exception:
        pass
    return cand1

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        import sys
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            # Preserve original traceback for caller
            raise
        if sys.version_info[0] < 3:
            # In Python 2, encode unicode to bytestring
            if isinstance(result, unicode):
                return result.encode('utf-8')
            # If already bytes, return as is
            return result
        # In Python 3, return result unchanged
        return result
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        # Prefer importlib.metadata on Python 3.8+
        import importlib.metadata as importlib_metadata
        try:
            return importlib_metadata.version(__name__)
        except Exception:
            return default
    except ImportError:
        # Fallback to pkg_resources if available
        try:
            import pkg_resources
            try:
                return pkg_resources.get_distribution(__name__).version
            except Exception:
                return default
        except ImportError:
            return default

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if pieces is None:
            return '+'
        # Handle string input
        if isinstance(pieces, str):
            return '.' if '+' in pieces else '+'
        # Handle iterable input
        for piece in pieces:
            if piece == '+':
                return '.'
        return '+'
    except Exception:
        # In case of invalid input or unexpected error, default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the input
    if isinstance(commands, (list, tuple)):
        command_list = list(commands)
    else:
        command_list = [commands]

    outputs = []

    for cmd in command_list:
        # Build the command to execute
        if isinstance(cmd, (list, tuple)):
            cmd_parts = list(cmd) + list(args)
        elif isinstance(cmd, str):
            import shlex
            cmd_parts = shlex.split(cmd) + list(args)
        else:
            raise ValueError(f"Unsupported command type: {type(cmd)}")

        if verbose:
            print(f"Running command: {' '.join(cmd_parts)}")

        # Prepare subprocess parameters
        try:
            proc = subprocess.Popen(
                cmd_parts,
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                env=env,
                close_fds=True
            )
        except OSError as e:
            raise RuntimeError(f"Failed to start command {cmd_parts}: {e}") from e

        stdout, stderr = proc.communicate()

        if verbose:
            if stdout:
                print(f"stdout: {stdout.decode(errors='ignore').strip()}")
            if not hide_stderr and stderr:
                print(f"stderr: {stderr.decode(errors='ignore').strip()}", file=sys.stderr)

        if proc.returncode != 0:
            err_msg = stdout.decode(errors='ignore') if stdout else ""
            err_msg += stderr.decode(errors='ignore') if stderr else ""
            raise RuntimeError(f"Command {' '.join(cmd_parts)} failed with return code {proc.returncode}: {err_msg.strip()}")

        outputs.append(stdout.decode(errors='ignore'))

    # Return the output of the last command, or join multiple outputs if desired
    return "\n".join(outputs) if len(outputs) > 1 else outputs[0] if outputs else ""

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            tuple(num_objects, good_objects) - number of objects checked and number of objects that passed validation.
        """
        # Determine the root of the hierarchy.  The method supports a few common patterns
        # (e.g., a `root` attribute, a `hierarchy_root` attribute, or a `objects` property that
        # contains the root elements).  If none of these exist, a clear exception is raised.
        root = None
        for name in ('root', 'hierarchy_root', 'objects'):
            if hasattr(self, name):
                root = getattr(self, name)
                break
        if root is None:
            raise AttributeError(
                "The instance does not expose a root or objects attribute required for hierarchy validation."
            )

        # Internal generator that recursively yields every object in the hierarchy.
        def _traverse(node):
            """Yield a node and all of its descendants.  This works for both object hierarchies
            (where children are available through a `children` attribute or a `sub_objects`
            list) and for simple dictionaries/lists.
            """
            yield node
            # Try common child access patterns
            children = None
            if isinstance(node, dict):
                children = node.get('children', node.get('sub_objects'))
            else:
                children = getattr(node, 'children', None) or getattr(node, 'sub_objects', None)
            if children is None:
                return
            if isinstance(children, (list, tuple)):
                for child in children:
                    yield from _traverse(child)
            elif isinstance(children, dict):
                for child in children.values():
                    yield from _traverse(child)
            # Anything else is treated as a leaf and ignored.

        num_objects = 0
        good_objects = 0

        # Helper functions that user supplied; if not defined this method by default is a no-op
        def _validate_object(node):
            if hasattr(self, '_validate_object'):
                return self._validate_object(node)
            # Default behaviour: if node is a dict, require a 'valid' key that is True
            if isinstance(node, dict) and 'valid' in node:
                if not node['valid']:
                    raise ValueError("Node marked as invalid")
            return True

        def _check_digest(node):
            if hasattr(self, '_check_digest'):
                return self._check_digest(node)
            # Default behaviour: if node has a digest and a data field,
            # check that digest matches data content using a simple sum.
            if isinstance(node, dict) and 'digest' in node and 'data' in node:
                if sum(bytearray(node['data'])) % 256 != node['digest']:
                    raise ValueError("Digest mismatch")
            return True

        try:
            for node in _traverse(root):
                num_objects += 1
                valid = True
                if validate_objects:
                    try:
                        _validate_object(node)
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[VALIDATION] Object {node} failed validation: {e}", flush=True)
                if check_digests:
                    try:
                        _check_digest(node)
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"[DIGEST] Object {node} digest check failed: {e}", flush=True)
                if valid:
                    good_objects += 1
        except Exception as ex:
            # Catch unexpected errors in traversal itself; report and continue
            if show_warnings:
                print(f"[ERROR] Unexpected error during hierarchy traversal: {ex}", flush=True)

        return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json
    from pathlib import Path

    # Resolve the root path that this instance uses.
    root_path = getattr(self, "root", None) or getattr(self, "root_path", None) or getattr(self, "storage_root", None)
    if not root_path:
        raise ValueError("The storage root path has not been set on this instance.")

    root = Path(root_path)

    # Create the root directory if it does not exist yet.
    if not root.exists():
        try:
            root.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise ValueError(f"Failed to create OCFL root directory {root!s}: {exc}") from exc
    else:
        # If the directory already exists, ensure it is empty.
        if any(root.iterdir()):
            raise ValueError(f"OCFL root {root!s} already exists and is not empty.")

    # Create required sub-directory structure.
    objects_dir = root / "objects"
    try:
        objects_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise ValueError(f"Failed to create objects directory {objects_dir!s}: {exc}") from exc

    # Create the repository descriptor file.
    descriptor_file = root / "ocfl-repo.json"
    if descriptor_file.exists():
        raise ValueError(f"Repository descriptor {descriptor_file!s} already exists.")
    repo_info = {
        "root_path": str(root.resolve()),
        "ocfl-spec-version": "1.0",
        "ocfl-core-version": "1.0",
        "compatible-ocfl-version": "1.0",
    }
    try:
        descriptor_file.write_text(json.dumps(repo_info, indent=2))
    except OSError as exc:
        raise ValueError(f"Failed to write repository descriptor {descriptor_file!s}: {exc}") from exc

    # Mark this instance as initialized.
    self.initialized = True
    return True

