def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError(f"Expected params to be a dict, got {type(params).__name__}")

    # Ensure bug_ids is iterable; treat None or empty as no ids
    if bug_ids is None:
        bug_ids = []

    if not hasattr(bug_ids, '__iter__') or isinstance(bug_ids, (str, bytes)):
        raise TypeError("bug_ids must be an iterable of ids")

    # Filter out any non‑numeric values and convert to strings
    ids = [str(bid) for bid in bug_ids if isinstance(bid, (int, str)) and str(bid).strip() != '']
    if ids:
        params['ids'] = ','.join(ids)
    else:
        # if empty or no valid ids, remove the key if present
        params.pop('ids', None)
    return params

def deep_merge_nodes(nodes):
    """
    Given a list of (ScalarNode, value) tuples, deep merge values with duplicate keys.
    Duplicate keys of MappingNode values are recursively merged, otherwise the last
    value wins.
    """
    # Helper to identify a MappingNode via its tag
    def is_mapping(node):
        return hasattr(node, "tag") and node.tag == "tag:yaml.org,2002:map"

    # Recursive merge of two lists of (ScalarNode, value) pairs
    def merge_value_lists(list1, list2):
        merged_dict = {}
        # Process list1 into dictionary
        for k, v in list1:
            merged_dict[k.value] = (k, v)
        # Process list2 with conflict resolution
        for k, v in list2:
            key_val = k.value
            if key_val in merged_dict:
                existing_k, existing_v = merged_dict[key_val]
                if is_mapping(existing_v) and is_mapping(v):
                    # Recursively merge mapping node values
                    merged_val = merge_value_lists(existing_v.value, v.value)
                    existing_v.value = merged_val
                    merged_dict[key_val] = (existing_k, existing_v)
                else:
                    # Override with the value from list2
                    merged_dict[key_val] = (k, v)
            else:
                merged_dict[key_val] = (k, v)
        return list(merged_dict.values())

    # Main merge logic over the whole nodes list
    merged = []
    for key, val in nodes:
        # Find if the key already exists
        existing_index = next(
            (i for i, (ek, ev) in enumerate(merged) if ek.value == key.value), None
        )
        if existing_index is None:
            # Key not seen before, add it
            merged.append((key, val))
        else:
            _, existing_val = merged[existing_index]
            if is_mapping(existing_val) and is_mapping(val):
                # Deep merge mapping nodes
                merged_val = merge_value_lists(existing_val.value, val.value)
                existing_val.value = merged_val
                merged[existing_index] = (key, existing_val)
            else:
                # Override with the new value
                merged[existing_index] = (key, val)
    return merged

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    parser = argparse.ArgumentParser()
    # No specific arguments are defined here; the parser is kept generic.
