def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate the parser has the expected attribute
    if not hasattr(parser, '_actions'):
        raise TypeError(f'Expected an argparse.ArgumentParser, got {type(parser).__name__}')

    flags = []
    for action in parser._actions:
        # Only consider actions that have option strings (i.e., flags)
        option_strings = getattr(action, 'option_strings', [])
        if option_strings:
            flags.extend(option_strings)

    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_results = {}
    remaining_by_parser = []

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_results[name] = namespace
            remaining_by_parser.append(remaining)
        except Exception:
            # If parsing fails for one parser, store an empty namespace
            parsed_results[name] = type('Namespace', (), {})()
            remaining_by_parser.append([])

    if not remaining_by_parser:
        remaining = list(unparsed_arguments)
    else:
        # Find arguments that were not consumed by any subparser
        common_remaining = set(remaining_by_parser[0])
        for rem in remaining_by_parser[1:]:
            common_remaining &= set(rem)

        # Preserve original ordering for the final remaining list
        remaining = [arg for arg in unparsed_arguments if arg in common_remaining]

    return parsed_results, remaining

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        return ''
    try:
        flags = []
        # `_actions` holds all argument actions; optional ones have non-empty option_strings
        for action in getattr(parser, '_actions', []):
            flags.extend(getattr(action, 'option_strings', []))
        # Filter out any empty strings and return a space-separated string
        return ' '.join(flag for flag in flags if flag)
    except Exception:
        # In case of any unexpected attribute errors or other runtime issues,
        # gracefully return an empty string.
        return ''

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import Counter
    cumulative = Counter()
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        cumulative.update(d)
    return dict(cumulative)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not url_args:
        return url
    # Convert url_args to a mapping if possible
    try:
        args_map = dict(url_args)
    except Exception:
        return url
    import re, urllib.parse

    # Pattern to capture placeholders like {placeholder}
    placeholder_pattern = re.compile(r'\{([a-zA-Z0-9_]+)\}')

    def _replace_match(match):
        key = match.group(1)
        if key in args_map:
            try:
                # Ensure the value is a string and URL‑encode it
                return urllib.parse.quote(str(args_map[key]), safe='')
            except Exception:
                # Fallback if quoting fails
                return str(args_map[key])
        # If the key is not provided in url_args, leave the placeholder unchanged
        return match.group(0)

    return placeholder_pattern.sub(_replace_match, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
