def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non‑negative")

    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of characters")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")

    # Ensure alphabet elements are unique single-character strings
    if len(set(alphabet)) != base:
        raise ValueError("alphabet must contain unique characters")
    for ch in alphabet:
        if not isinstance(ch, str):
            raise TypeError("alphabet elements must be strings")
        if len(ch) != 1:
            raise ValueError("alphabet elements must be single characters")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    # Conversion
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Padding (prepend with the zero character)
    if padding is not None and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits

    return "".join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    # Input validation
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    new_key = f"register_{register_number}"

    for flow_key, flow_obj in flow_params.items():
        # Handle nested dictionaries directly
        if isinstance(flow_obj, dict):
            if register_value in flow_obj:
                flow_obj[new_key] = flow_obj.pop(register_value)
        # Handle list of dictionaries if present
        elif isinstance(flow_obj, list):
            for item in flow_obj:
                if isinstance(item, dict) and register_value in item:
                    item[new_key] = item.pop(register_value)
        # If flow_obj is neither dict nor list, skip silently

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    try:
        if value is None:
            raise ValueError("value cannot be None")
        if not isinstance(value, str):
            value = str(value)

        if arg is None:
            arg = ''
        if not isinstance(arg, str):
            arg = str(arg)

        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError(f"Error in replace_dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses expects a class (type) object")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subcls = current.__subclasses__()
        except Exception:
            continue
        for c in subcls:
            if c not in seen:
                seen.add(c)
                stack.append(c)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols.")
    # Ensure alphabet symbols are unique
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet must contain unique symbols.")
    # Build mapping from symbol to numeric value
    symbol_to_value = {symbol: i for i, symbol in enumerate(alphabet)}
    result = 0
    for char in string:
        if char not in symbol_to_value:
            raise ValueError(f"Character '{char}' not found in alphabet.")
        result = result * base + symbol_to_value[char]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # First, use sys.platform which is the standard way to detect the OS
        import sys
        if sys.platform == 'darwin':
            return True
    except Exception:
        # If for some reason sys.platform fails, fall back to os.uname()
        pass

    # Fallback: os.uname() may provide the system name 'Darwin' on macOS
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        # Any failure implies we cannot confirm macOS
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:
        rules = {
            '*.cpp':
                {'a': 'arf', 'b': 'bark', 'c': 'coo'},
            '*.h':
                {'h': 'help'}
        }
        regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError(f"Expected dict, got {type(item).__name__}")

    new_dict = {}
    for key, value in item.items():
        try:
            if isinstance(key, str) and ('*' in key or '?' in key):
                # Escape all regex metacharacters, then replace escaped wildcards
                escaped = re.escape(key)
                pattern = '^' + escaped.replace(r'\*', '.*').replace(r'\?', '.') + '$'
                new_dict[pattern] = value
            else:
                new_dict[key] = value
        except Exception:
            # Preserve original key/value if any error occurs
            new_dict[key] = value
    return new_dict

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    # Resolve auto platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    # Use shlex with appropriate mode; shlex.posix=False mimics Windows quoting
    if platform == 1:
        return shlex.split(s, posix=True)
    elif platform == 0:
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f"Unsupported platform value: {platform!r}")

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files,
    return those files as a single string with each filename separated by a comma."""
    # Build the git command to list ignored files
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    if ignored:
        # If `ignored` is a list of additional git arguments, extend the command
        if isinstance(ignored, (list, tuple)):
            cmd.extend(ignored)
        else:
            # Treat single string argument as an additional git flag or path
            cmd.append(ignored)
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, text=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"git command failed: {e.output}") from e
    # Convert output into a sorted list of filenames
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    # Return a comma-separated string of filenames
    return ','.join(files)

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # Only Windows platforms can have Git Bash
    if os.name != "nt":
        return False

    env = os.environ

    # Check common environment variables set by Git Bash
    if "MSYSTEM" in env:
        return True
    if "OSTYPE" in env:
        # Some installations set OSTYPE to msys, mingw, or cygwin
        return env["OSTYPE"].lower().startswith(("msys", "mingw", "cygwin"))

    # Look in the PATH for typical Git Bash directory names
    path_dirs = env.get("PATH", "").split(os.pathsep)
    for d in path_dirs:
        if d.lower().startswith(("mingw", "msys", "cygwin")):
            return True

    return False

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Build the full command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)

    if args:
        if isinstance(args, str):
            cmd.append(args)
        else:
            cmd.extend(args)

    # Optional verbosity
    if verbose:
        print("Running command:", " ".join(cmd))

    # Determine where to send stderr
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        # Execute the command, capturing stdout
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            check=True,
            text=True
        )
        return result
    except subprocess.CalledProcessError as e:
        # Provide a clear error message and re‑raise
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}") from e

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    # If already an IPv4Address instance, return True
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        addr = ipaddress.ip_address(target)
    except (ValueError, TypeError):
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Use safe_dump to avoid arbitrary tag handling
    try:
        yaml_output = yaml.safe_dump(
            obj,
            Dumper=dumper,
            default_flow_style=False,
            allow_unicode=True,
        )
    except Exception as exc:
        raise RuntimeError("YAML dump failed: %s" % exc) from exc

    # In Python 2, safe_dump may return a byte string; convert it to unicode
    if isinstance(yaml_output, bytes):
        yaml_output = yaml_output.decode("utf-8")
    return yaml_output

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and convert shape
    try:
        shape = tuple(shape)
    except Exception as exc:
        raise TypeError("shape must be convertible to a tuple") from exc
    if not isinstance(shape, tuple):
        raise TypeError("shape must be a tuple of integers")
    for idx, dim in enumerate(shape):
        if not isinstance(dim, int) or dim < 0:
            raise ValueError(f"shape element at index {idx} must be a non‑negative integer, got {dim!r}")

    # Validate and convert dtype
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as exc:
            raise TypeError("dtype must be a NumPy dtype or convertible to one") from exc

    # Create the array
    try:
        arr = np.empty(shape, dtype)
    except Exception as exc:
        raise RuntimeError(f"Unable to create array with shape {shape} and dtype {dtype}") from exc

    return arr

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_map = {}
    error_records = []
    overrides = overrides or {}

    for filename in config_filenames:
        # Ensure file exists
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as e:
            er = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to read {filename}: {e}',
                args=None,
                exc_info=None
            )
            error_records.append(er)
            continue

        # Determine parser based on extension
        _, ext = os.path.splitext(filename.lower())
        parsed = None
        try:
            if ext in {'.yaml', '.yml'}:
                parsed = yaml.safe_load(raw) or {}
            elif ext == '.json':
                parsed = json.loads(raw)
            elif ext == '.toml':
                parsed = toml.loads(raw)
            elif ext in {'.ini', '.cfg'}:
                cp = configparser.ConfigParser()
                cp.read_string(raw)
                parsed = {s: dict(cp.items(s)) for s in cp.sections()}
            else:
                # Unsupported extension, try JSON as fallback
                parsed = json.loads(raw)
        except Exception as e:
            er = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to parse {filename}: {e}',
                args=None,
                exc_info=None
            )
            error_records.append(er)
            continue

        # Validate that parsed is a mapping
        if not isinstance(parsed, dict):
            er = logging.LogRecord(
                name='config_loader',
                level=logging.WARNING,
                pathname=filename,
                lineno=0,
                msg=f'Parsed {filename} is not a mapping; got {type(parsed).__name__}.',
                args=None,
                exc_info=None
            )
            error_records.append(er)

        # Resolve environment variables if requested
        def env_substitute(obj):
            if isinstance(obj, str):
                return os.path.expandvars(obj)
            if isinstance(obj, dict):
                return {k: env_substitute(v) for k, v in obj.items()}
            if isinstance(obj, list):
                return [env_substitute(v) for v in obj]
            return obj

        if resolve_env:
            parsed = env_substitute(parsed)

        # Apply overrides
        if isinstance(parsed, dict):
            parsed.update(overrides)

        config_map[filename] = parsed

    return config_map, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj`` in case
    it is a string using UTF‑8. If ``obj`` is already a bytes object
    (or any other type), it is returned unchanged.
    """
    try:
        if isinstance(obj, str):
            return obj.encode('utf-8')
    except Exception:
        # If encoding fails for some reason, fall back to returning the original object
        return obj
    return obj

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Defensive: Ensure we have an iterable
        try:
            iter(values)
        except Exception:
            raise TypeError("values must be an iterable of strings")

        # Convert each entry to a string, ignoring None entries
        bookmarks = []
        for v in values:
            if v is None:
                continue
            try:
                bookmarks.append(str(v))
            except Exception as exc:
                # Log or raise a descriptive error
                raise ValueError(f"Unable to convert bookmark value '{v}' to string: {exc}") from exc

        # Return a new instance of the class, passing the parsed list
        # This assumes the constructor accepts a keyword argument named 'bookmarks'.
        # Adjust the argument name if the actual constructor differs.
        return cls(bookmarks=bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle string or bytes directly
    if isinstance(seq, (str, bytes)):
        # If bytes, convert to string
        if isinstance(seq, bytes):
            try:
                seq_str = seq.decode()
            except Exception:
                seq_str = str(seq)
        else:
            seq_str = seq
        return seq_str, seq_str.__class__.__name__

    # Handle file-like objects (something with a read method)
    if hasattr(seq, "read"):
        try:
            # Try to use the provided buffer size if any
            if bufsize is not None:
                data = seq.read(bufsize)
            else:
                data = seq.read()
        except Exception as exc:
            raise TypeError(f"Unable to read from file-like object: {exc}") from exc
        # If read returns bytes, convert to string
        if isinstance(data, bytes):
            try:
                data = data.decode()
            except Exception:
                data = str(data)
        return data, "file"

    # Handle list or tuple of characters (or other iterable)
    if isinstance(seq, (list, tuple)):
        try:
            # Try to join elements into a string, supporting non-string elements by converting them
            seq_str = "".join(str(x) for x in seq)
            return seq_str, "string"
        except Exception as exc:
            raise TypeError(f"Cannot convert list/tuple into string: {exc}") from exc

    # If seq is an iterable but not a sequence type, try to join into string
    try:
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
            seq_str = "".join(str(x) for x in seq)
            return seq_str, "string"
    except Exception:
        pass

    # Fallback: return the original object and its type name
    return seq, seq.__class__.__name__

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Sanity check: iface should be a class or type
    if not isinstance(iface, type):
        raise TypeError("iface must be a class type")

    # Determine the candidate type: class or instance
    is_class_candidate = isinstance(candidate, type)

    # 1. Direct subclass/instance check
    try:
        if is_class_candidate:
            if issubclass(candidate, iface):
                return True
        else:
            if isinstance(candidate, iface):
                return True
    except Exception:
        # Any error (e.g., not comparable types) is ignored here
        pass

    # 2. Check abstract methods, if any
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        for name in abstract_methods:
            # Obtain the attribute on the candidate; use fallback if candidate is a class
            try:
                attr = getattr(candidate, name)
            except Exception:
                if tentative:
                    return False
                raise TypeError(f"Candidate {candidate!r} does not implement abstract method '{name}'")

            if not callable(attr):
                if tentative:
                    return False
                raise TypeError(f"Candidate {candidate!r} method '{name}' is not callable")

    # 3. Fallback: if candidate is None or not a valid object
    if candidate is None:
        if tentative:
            return False
        raise TypeError("candidate cannot be None")

    # If all checks passed, candidate satisfies the interface
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Helper to find the most derived common metaclass of two metaclasses
    def _common_meta(meta1, meta2):
        if meta1 is None:
            return meta2
        if meta2 is None:
            return meta1
        # Find earliest metaclass that is a supertype of both
        for m in meta1.__mro__:
            if m in meta2.__mro__:
                return m
        return None

    # If an explicit metaclass is supplied, it takes precedence
    # but it must be compatible with the bases.
    if explicit_mc is not None:
        # Verify explicit_mc is a metaclass (subclass of type)
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        # Determine the common base metaclass of the bases
        base_meta = None
        for b in bases:
            if b is None:
                continue
            try:
                bm = b.__class__
            except Exception:
                bm = None
            base_meta = _common_meta(base_meta, bm)
        # If no bases or no common base, use type
        if base_meta is None:
            base_meta = type
        # Check compatibility
        if not issubclass(explicit_mc, base_meta):
            raise TypeError(
                f"Explicit metaclass {explicit_mc!r} is not compatible "
                f"with bases meta {base_meta!r}"
            )
        return explicit_mc

    # No explicit metaclass: derive from bases
    common_meta = None
    for b in bases:
        if b is None:
            continue
        try:
            meta = b.__class__
        except Exception:
            meta = None
        common_meta = _common_meta(common_meta, meta)

    # Default to 'type' if no bases or no shared metaclass
    return common_meta or type

def popitem(self):
    """Remove and return the (key, value) pair least recently used."""
    # The least recently used item is the node just before the tail sentinel.
    node = self._tail[3]
    if node is self._head:
        raise KeyError('Cache is empty')
    self._find_lt(node[0])
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return (key, value)
    except KeyError:
        raise KeyError('dictionary is empty')

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    ``self`` is expected to have an attribute that contains a list of
    values that the ``in`` clause should match.  The exact attribute name is
    unspecified, so this method attempts to retrieve it heuristically.
    The resulting regular expression will match *exactly* one of the
    provided values.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Determine the attribute that holds the list of values to match
    values = None
    for name in ("_in_values", "_in_params", "in_values", "in_params"):
        if hasattr(self, name):
            values = getattr(self, name)
            break

    if values is None:
        raise AttributeError(
            "No suitable attribute found for IN values (tried "
            "_in_values, _in_params, in_values, in_params)"
        )

    # validate that values is an iterable of strings
    try:
        values_iter = iter(values)
    except TypeError:
        raise TypeError(f"IN values must be an iterable, got {type(values)!r}")

    # Escape each value and build alternation
    escaped = []
    for v in values_iter:
        if not isinstance(v, str):
            raise TypeError(
                f"Each value in IN list must be a string, got {type(v)!r}"
            )
        escaped.append(re.escape(v))

    if not escaped:
        # If no values were provided, create a pattern that matches nothing
        return re.compile(r"(?!)")

    # Wrap in start/end anchors so we match the whole token exactly
    alternation = "|".join(escaped)
    pattern_str = r"^(?:%s)$" % alternation

    return re.compile(pattern_str)

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        return _converting._Converter()
    except Exception as exc:
        raise RuntimeError("Failed to instantiate parameter style converter") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError(
            f"format_dt expects a datetime.datetime instance, got {type(dt).__name__}"
        )
    # Ensure the datetime is UTC. If it already has tzinfo, convert it; otherwise assume UTC.
    if dt.tzinfo is not None:
        dt_utc = dt.astimezone(datetime.timezone.utc)
    else:
        dt_utc = dt.replace(tzinfo=datetime.timezone.utc)
    # Format as an ISO‑8601 string with a trailing 'Z' to denote UTC.
    # Omit fractional seconds when the value is zero for consistency with many D* node APIs.
    if dt_utc.microsecond:
        formatted = dt_utc.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        # Trim trailing zeros in microseconds
        formatted = formatted.rstrip("0").rstrip(".") + "Z"
    else:
        formatted = dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    return formatted

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Regex to find URLs starting with http://, https:// or www.
    url_pattern = re.compile(r'\b((?:http[s]?://|www\.)\S+)', re.IGNORECASE)

    def _replace(match):
        try:
            url = match.group(0)
            href = url
            if href.lower().startswith('www.'):
                href = 'http://' + href
            # Add attributes to the link
            attrs = ' target="_blank" rel="noopener noreferrer"'
            return f'<a href="{href}"{attrs}>{url}</a>'
        except Exception:
            # In case of any unforeseen error, fall back to plain text
            return match.group(0)

    return url_pattern.sub(_replace, text)

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    # Tag must not be empty
    if not tag:
        return False
    # Define maximum allowed length for a tag
    MAX_LENGTH = 30
    if len(tag) > MAX_LENGTH:
        return False
    # Allowed characters: alphanumeric, underscore and hyphen
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
    for char in tag:
        if char not in allowed_chars:
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    if node is None:
        return result
    # In ElementTree, an element is iterable over its child elements.
    try:
        for child in node:
            tag = child.tag
            if tag in result:
                # If tag already present, store multiple children in a list.
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception as e:
        raise TypeError(f"Expected an ElementTree element, got {type(node)!r}") from e
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        logger.warning("parse_diaspora_webfinger: received empty document")
        return None
    # try JSON first
    try:
        data = json.loads(document)
    except Exception:
        # fall back to XRD/XML parsing
        try:
            root = ET.fromstring(document)
        except Exception:
            logger.warning("parse_diaspora_webfinger: invalid document format")
            return None
        # Namespaces can be present, so gather without namespace for simplicity
        def strip_ns(tag):
            return tag.split('}')[-1]
        result = {}
        subject = root.findtext('.//{*}Subject') or root.findtext('.//Subject')
        if subject:
            result['subject'] = subject.strip()
        links = root.findall('.//{*}Link') or root.findall('.//Link')
        for link in links:
            rel = link.attrib.get('rel')
            href = link.attrib.get('href')
            template = link.attrib.get('template')
            url = href or template
            if not url:
                continue
            rel_key = rel.replace('http://webfinger.net/rel/', '').replace('http://example.org/rel/', '')
            if rel_key == 'hcard':
                result['hcard_url'] = url
            elif rel_key == 'lrdd':
                result['lrdd_url'] = url
        return result
    # JSON parsing
    result = {}
    subject = data.get('subject')
    if subject:
        result['subject'] = subject
    links = data.get('links', [])
    for link in links:
        rel = link.get('rel')
        href = link.get('href')
        template = link.get('template')
        url = href or template
        if not url:
            continue
        rel_key = rel.replace('http://webfinger.net/rel/', '').replace('http://example.org/rel/', '')
        if rel_key == 'hcard':
            result['hcard_url'] = url
        elif rel_key == 'lrdd':
            result['lrdd_url'] = url
    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning(
            "retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle
        )
        return None
    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    # Accept single directory or iterable of directories
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    filenames = []

    for d in dirs:
        try:
            for entry in os.listdir(d):
                full_path = os.path.join(d, entry)
                if not os.path.isfile(full_path):
                    continue

                if spec_option is None:
                    filenames.append(full_path)
                else:
                    # If spec_option is a string, treat it as a pattern with fnmatch
                    if isinstance(spec_option, str):
                        if fnmatch.fnmatch(entry, spec_option):
                            filenames.append(full_path)
                    else:
                        # Assume callable: try to use it as a predicate on the filename
                        try:
                            if spec_option(entry):
                                filenames.append(full_path)
                        except Exception:
                            # Skip if predicate raises an error
                            continue
        except Exception:
            # Skip directories that cannot be accessed
            continue

    return sorted(filenames)

