@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content is required")

    try:
        data = yaml.safe_load(spec_content)
    except Exception as exc:
        raise IRValidatorException(f"Failed to parse YAML: {exc}")

    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must resolve to a mapping")

    # Determine required fields; subclasses may override REQUIRED_FIELDS
    required = getattr(cls, "REQUIRED_FIELDS", None)
    if required is None:
        # Default minimal set if not specified
        required = ["name", "version", "spec"]

    missing = [fld for fld in required if fld not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file must be provided")

    try:
        # Open and load YAML safely
        with open(yaml_file, "r") as fp:
            data = yaml.safe_load(fp)
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file not found: {yaml_file}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}")
    except Exception as e:
        raise IRValidatorException(f"Unexpected error reading {yaml_file}: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file {yaml_file} does not contain a dictionary at top level")

    # Determine required fields; subclass can override cls.REQUIRED_FIELDS
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing mandatory fields in {yaml_file}: {', '.join(missing)}"
        )

    # Optional: perform more detailed validation if the class provides a validate method
    if hasattr(cls, "validate"):
        try:
            cls.validate(data)
        except Exception as e:
            raise IRValidatorException(f"Validation failed for {yaml_file}: {e}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Make a copy to avoid mutating the caller's dict
    pending = dict(parser_dict)
    resolved = {}

    def _resolve(group_name, stack=None):
        if stack is None:
            stack = set()
        # Return already resolved group
        if group_name in resolved:
            return resolved[group_name]
        # Detect undefined include
        if group_name not in pending:
            raise KeyError(f"Included group '{group_name}' not found in parser_dict")
        # Detect circular inclusion
        if group_name in stack:
            cycle = " -> ".join(list(stack) + [group_name])
            raise RuntimeError(f"Circular include detected: {cycle}")
        stack.add(group_name)

        group = pending[group_name]
        if not isinstance(group, dict):
            # If the value is not a dict there's nothing to include
            resolved[group_name] = group
            stack.remove(group_name)
            return group

        merged = {}
        # Process include directives if present
        include = group.get('include')
        if include:
            if isinstance(include, str):
                include = [include]
            if not isinstance(include, (list, tuple)):
                raise TypeError(f"Include for '{group_name}' must be a string or list")
            for inc_name in include:
                inc_def = _resolve(inc_name, stack)
                if isinstance(inc_def, dict):
                    merged.update(inc_def)
        # Merge own keys, overriding any duplicates from included groups
        for k, v in group.items():
            if k == 'include':
                continue
            merged[k] = v
        resolved[group_name] = merged
        stack.remove(group_name)
        return merged

    # Resolve every group/key in the dictionary
    for name in pending:
        _resolve(name)

    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Gather the external spec values, falling back to empty dicts if unavailable.
    try:
        spec_vals = getattr(self, "spec", {})
        if not isinstance(spec_vals, dict):
            # Try to convert to a dict if possible
            spec_vals = getattr(spec_vals, "to_dict", lambda: {})()
    except Exception:
        spec_vals = {}

    try:
        default_spec_vals = getattr(self, "_default_spec", {})
        if not isinstance(default_spec_vals, dict):
            default_spec_vals = getattr(default_spec_vals, "to_dict", lambda: {})()
    except Exception:
        default_spec_vals = {}

    # Result dictionary for resolved defaults
    resolved = {}

    # Iterate over defined arguments if available
    for arg in getattr(self, "args", []):
        # Skip non‑option-like objects
        if not hasattr(arg, "name"):
            continue
        name = arg.name

        # Priority: spec -> default spec -> argument default -> None
        if name in spec_vals:
            value = spec_vals[name]
        elif name in default_spec_vals:
            value = default_spec_vals[name]
        elif hasattr(arg, "default"):
            # Assume a real default is provided (sentinel handling is user‑specific)
            value = getattr(arg, "default", None)
        else:
            value = None

        # Handle options that contain nested schemes (e.g., dict options)
        if hasattr(arg, "scheme") and arg.scheme:
            # Resolve nested defaults recursively if the scheme exposes get_spec_defaults
            nested_spec = None
            if isinstance(value, dict):
                nested_spec = value
            try:
                nested_default = getattr(arg.scheme, "get_spec_defaults", lambda: {})()
            except Exception:
                nested_default = {}
            if nested_spec is not None:
                # Merge explicit nested values with scheme defaults
                nested_spec.update(nested_default)
                resolved[name] = nested_spec
            else:
                resolved[name] = nested_default
        else:
            resolved[name] = value

    return resolved

