def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Attempt to locate the command specifications
    specs = None
    if hasattr(self, "_command_specs"):
        # Common pattern: a dict mapping command names to option specs
        try:
            specs = self._command_specs[command_name]
        except KeyError:
            raise KeyError(f"Command '{command_name}' not found in _command_specs")

    elif hasattr(self, "commands"):
        # Alternate pattern: a dict mapping command names to parser objects
        try:
            parser = self.commands[command_name]
        except KeyError:
            raise KeyError(f"Command '{command_name}' not found in commands")
        if hasattr(parser, "get_option_list"):
            # Some parsers expose a method to fetch options
            specs = parser.get_option_list()
        elif hasattr(parser, "options"):
            # Fall back to an attribute that might hold options
            specs = parser.options
        else:
            raise AttributeError("Unable to extract options from the parser object")

    else:
        raise NotImplementedError("No supported attribute found for command specs")

    # Convert whatever structure we got into a list of option identifiers
    if specs is None:
        return []

    # If specs is already a list/tuple, return a copy
    if isinstance(specs, (list, tuple)):
        return list(specs)

    # If specs is a dict mapping option names to specs, return the keys
    if isinstance(specs, dict):
        return list(specs.keys())

    # If specs is an object with an attribute that lists options
    if hasattr(specs, "options"):
        return list(specs.options)

    # Fallback: if it's an iterator or generator
    try:
        return list(specs)
    except TypeError:
        # If we cannot iterate, fall back to an empty list
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the command's option list
    try:
        options = self.commands[command_name]
    except KeyError:
        # Command not found
        return None

    # Search for the option specification by name
    for opt in options:
        # Option might be stored as a dict
        if isinstance(opt, dict):
            if opt.get("name") == argument_name:
                return opt
        else:
            # Assume it's an object with a 'name' attribute or property
            opt_name = getattr(opt, "name", None)
            if opt_name == argument_name:
                return opt

    # If no matching option spec is found, return None
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not args:
        return []
    silent = []
    for arg in args:
        if isinstance(arg, str) and arg.startswith('-'):
            silent.append(arg.lstrip('-'))
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []

    # Iterate over each option specification
    for opt in options_spec:
        if not isinstance(opt, dict):
            # Skip non-dict entries
            continue

        # Skip options that do not have a required_when condition
        if 'required_when' not in opt:
            continue

        condition = opt['required_when']

        # Determine whether the condition is satisfied
        satisfied = False
        try:
            if callable(condition):
                # If the condition is a function, call it with command_name and args
                satisfied = bool(condition(command_name, args))
            elif isinstance(condition, dict):
                # If the condition is a dict, look up the command name
                if command_name in condition:
                    satisfied = bool(condition[command_name])
            elif isinstance(condition, (list, tuple, set)):
                # If the condition is a list/tuple/set of commands, check membership
                satisfied = command_name in condition
            else:
                # Otherwise treat the value itself as a boolean flag
                satisfied = bool(condition)
        except Exception:
            # In case the condition evaluation fails, treat as unsatisfied
            satisfied = False

        if satisfied:
            # Prefer 'arg' key, fall back to 'name' if present
            arg_name = opt.get('arg') or opt.get('name')
            if arg_name:
                required_args.append(arg_name)

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # args may be a dict mapping name -> arg dict or a list of such dicts
    if not isinstance(args, (dict, list)):
        raise TypeError(f"args must be a dict or a list, got {type(args).__name__}")

    if isinstance(args, dict):
        items = args.items()
    else:
        # treat each list item as a mapping or dict with one key/value pair
        items = ((f"[list-item {i}]", item) for i, item in enumerate(args))

    for arg_name, arg_attrs in items:
        if not isinstance(arg_attrs, dict):
            raise TypeError(f"argument {arg_name!r} attributes must be a dict, got {type(arg_attrs).__name__}")

        # Only validate if a value is present
        if "value" not in arg_attrs:
            continue
        value = arg_attrs["value"]

        # Length constraint may be under "length" or "max_length"
        maxlen = arg_attrs.get("length", arg_attrs.get("max_length"))
        if maxlen is None:
            continue

        if not isinstance(maxlen, int):
            raise TypeError(
                f"length for argument {arg_name!r} must be an integer, got {type(maxlen).__name__}"
            )
        if maxlen < 0:
            raise ValueError(
                f"length for argument {arg_name!r} must be non-negative, got {maxlen}"
            )

        try:
            actual_length = len(value)
        except TypeError as exc:
            raise TypeError(
                f"argument {arg_name!r} with value {value!r} has no length"
            ) from exc

        if actual_length > maxlen:
            raise ValueError(
                f"argument {arg_name!r} length {actual_length} exceeds maximum allowed {maxlen}"
            )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Retrieve the argument specifications from parsed YAML.
        arg_specs = self.parsed_yaml.get('args', {})
        # Normalize the specifications dictionary if it was given as a list.
        if isinstance(arg_specs, list):
            spec_dict = {}
            for item in arg_specs:
                if isinstance(item, dict):
                    for key, value in item.items():
                        spec_dict[key] = value
        else:
            spec_dict = arg_specs or {}

        # Validate each provided argument against its allowed choices (if any).
        for arg_name, arg_value in args.items():
            arg_def = spec_dict.get(arg_name)
            if not arg_def:
                # Argument not defined in the specification; skip validation.
                continue
            choices = arg_def.get('choices')
            # Only validate when a list/tuple/set of choices is provided.
            if isinstance(choices, (list, tuple, set)):
                if arg_value not in choices:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': {arg_value!r}. "
                        f"Allowed choices are: {choices}"
                    )
        # No return value needed; validation errors raise exceptions.

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable
    try:
        iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of values")

    # Determine the bounds from the instance; allow multiple naming conventions
    min_val = getattr(self, "min_", None) or getattr(self, "min", None)
    max_val = getattr(self, "max_", None) or getattr(self, "max", None)

    # If neither bound is provided, nothing to validate
    if min_val is None and max_val is None:
        return args

    # Validate each value in the iterable
    for idx, val in enumerate(args):
        # Skip non-numeric values
        if not isinstance(val, (int, float, complex)):
            continue

        if min_val is not None and val < min_val:
            raise ValueError(
                f"Argument at position {idx} with value {val} is below the minimum of {min_val}"
            )
        if max_val is not None and val > max_val:
            raise ValueError(
                f"Argument at position {idx} with value {val} exceeds the maximum of {max_val}"
            )

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not subcommand or not isinstance(subcommand, str):
        raise ValueError(f"Invalid subcommand: {subcommand!r}")
    if not type_name or not isinstance(type_name, str):
        raise ValueError(f"Invalid type_name: {type_name!r}")
    if not option_name or not isinstance(option_name, str):
        raise ValueError(f"Invalid option_name: {option_name!r}")
    if spec_option is None:
        raise ValueError("spec_option cannot be None")

    # Determine the actual callable/type that will be used
    if isinstance(spec_option, dict) and "__type__" in spec_option:
        # Use the generic construct helper that expects a mapping with '__type__'
        try:
            arg_type = self.construct(spec_option)
        except Exception as exc:
            raise ValueError(
                f"Failed to construct complex type '{type_name}' for option "
                f"'{option_name}' in subcommand '{subcommand}': {exc}"
            ) from exc
    elif callable(spec_option):
        arg_type = spec_option
    else:
        raise TypeError(
            f"Unsupported spec_option type for complex argument type "
            f"'{type_name}': {type(spec_option).__name__}"
        )

    # Store the type in a registry (if the instance has such an attribute)
    registry = getattr(self, "_complex_types", None)
    if registry is None:
        registry = {}
        self._complex_types = registry
    registry[(subcommand, type_name)] = arg_type

    return arg_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: a dictionary of collected command‑line arguments.
    :return: tuple of two flat dictionaries (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Defensive check: ensure we have a mapping to iterate over
    if args is None:
        return control_args, nested_args
    if not isinstance(args, dict):
        # If args is not a dict, we cannot split it reliably.
        raise TypeError(
            f"Expected args to be a dict, got {type(args).__name__}"
        )

    for key, value in args.items():
        if not isinstance(key, str):
            # Skip non‑string keys – they cannot be processed
            continue
        # Normalize key for comparison
        key = key.strip()
        if key.startswith("control."):
            # Remove the prefix and store in control dict
            control_key = key[len("control.") :]
            control_args[control_key] = value
        elif key.startswith("custom."):
            # Custom arguments are treated as nested variables;
            # strip the custom. prefix before storing
            nested_key = key[len("custom.") :]
            nested_args[nested_key] = value
        else:
            # Any other key is considered a nested argument
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars (dict, list of dicts, or sequences of key/value pairs)
        :return: Updated dictionary with merged values
        """
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
        if extra_vars is None:
            return vars_dict
        # Helper to update a single mapping
        def _update_from_mapping(mapping):
            if not isinstance(mapping, dict):
                raise TypeError(f"Each extra var mapping must be a dict, got {type(mapping).__name__}")
            vars_dict.update(mapping)
        # Handle single mapping
        if isinstance(extra_vars, dict):
            _update_from_mapping(extra_vars)
        # Handle list/tuple of mappings or key/value pairs
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    _update_from_mapping(item)
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                elif isinstance(item, str):
                    if "=" in item:
                        key, value = item.split("=", 1)
                        vars_dict[key] = value
                    else:
                        continue  # ignore malformed string
                else:
                    raise TypeError(f"Unsupported item type in extra_vars: {type(item).__name__}")
        else:
            raise TypeError(f"extra_vars must be None, a dict, or a list/tuple, got {type(extra_vars).__name__}")
        return vars_dict

