def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper to detect boolean-like strings
    def _str_to_bool(v):
        tru = {"true", "t", "yes", "y", "1"}
        fls = {"false", "f", "no", "n", "0"}
        low = v.lower()
        if low in tru:
            return True
        if low in fls:
            return False
        raise ValueError()

    # Helper to convert to int/float
    def _str_to_number(v):
        try:
            return int(v)
        except ValueError:
            try:
                return float(v)
            except ValueError:
                raise ValueError()

    # Helper to parse comma separated lists
    def _str_to_list(v):
        parts = [p.strip() for p in v.split(",")]
        # Attempt to convert each element individually
        new_parts = []
        for part in parts:
            try:
                new_parts.append(_str_to_bool(part))
            except ValueError:
                try:
                    new_parts.append(_str_to_number(part))
                except ValueError:
                    new_parts.append(part)
        return new_parts

    # Iterate over a copy to avoid runtime dictionary changes
    for key, val in list(values_dict.items()):
        # Only process string values
        if isinstance(val, str):
            # Attempt boolean conversion first
            try:
                values_dict[key] = _str_to_bool(val)
                continue
            except ValueError:
                pass
            # If value contains commas, treat as list
            if "," in val:
                try:
                    values_dict[key] = _str_to_list(val)
                    continue
                except ValueError:
                    pass
            # Attempt numeric conversion
            try:
                values_dict[key] = _str_to_number(val)
                continue
            except ValueError:
                pass
            # Fall back: keep original string
            values_dict[key] = val
        # For non-string types, leave unchanged
    return  # values_dict is modified in place
