def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        from pathlib import Path
        import json
    except Exception as exc:
        raise ImportError("Required modules (pathlib, json) not available.") from exc

    # Normalise the directory path
    plugin_path = Path(plugin_dir) if not isinstance(plugin_dir, (str, Path)) else Path(plugin_dir)

    # Verify the directory exists
    if not plugin_path.is_dir():
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory or does not exist")

    # Locate the plugin spec file (default to 'plugin.json')
    spec_file = plugin_path / "plugin.json"
    if not spec_file.is_file():
        raise FileNotFoundError(f"Plugin specification file 'plugin.json' not found in '{plugin_dir}'")

    # Read and parse the JSON spec
    try:
        with spec_file.open("r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON spec file '{spec_file}': {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error reading plugin spec file '{spec_file}': {e}") from e

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Return the flattened dictionary
    return _flatten(spec_data)
